python3 - <<'PY'
p='src/types/checker/functions/resolution/call.rs'
s=open(p).read()
old = """                    let specialized_ty =
                        Self::specialize_generic_array_param_hint(&declared_ty, &ty);
                    param_types.push((decl.params[arg_idx].clone(), specialized_ty));"""
new = """                    // A BY-REFERENCE array parameter keeps its declared `array` — that is,
                    // `array<mixed>` — instead of being specialized to the argument's element
                    // type. The callee may store ANY value into it and that store lands in the
                    // CALLER's storage, so compiling the body for `array<int>` and then widening
                    // it mid-body (a loop storage contract, an element write) rewrites the
                    // caller's array to boxed slots while the caller still reads raw ones.
                    // `function f(array &$a) { foreach ($a as $k => $v) { $a[$k] = $v * 2; } }`
                    // over `[1, 2, 3]` printed three ADDRESSES for exactly that reason. Keeping
                    // the declared type makes the widening the CALL SITE's job, where
                    // `ir_lower::expr::call_arg_coercion` already converts the caller's local
                    // and re-types it.
                    let by_ref = decl.ref_params.get(arg_idx).copied().unwrap_or(false);
                    let specialized_ty = if by_ref {
                        declared_ty.clone()
                    } else {
                        Self::specialize_generic_array_param_hint(&declared_ty, &ty)
                    };
                    param_types.push((decl.params[arg_idx].clone(), specialized_ty));"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('by-ref specialization disabled')
